import type { BankQuestion } from "@/lib/bank";

/** Biotechnology: Principles and Applications (Biology (NEET)): 134 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-biotechnology-1","question":"The first restriction endonuclease to be isolated, in 1968, was:","options":["Taq polymerase","BamHI","EcoRI","Hind II"],"answer":3,"explanation":"Hind II, which always cuts DNA at a particular point by recognising a specific sequence of six base pairs, was the first restriction endonuclease isolated. EcoRI was characterised later.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-2","question":"Agarose, the matrix most commonly used for gel electrophoresis of DNA, is a natural polymer extracted from:","options":["Crustacean shells","Cotton fibres","Sea weeds","Bacterial cell walls"],"answer":2,"explanation":"Agarose is a natural polymer extracted from sea weeds. DNA fragments move through the agarose matrix according to their size.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-3","question":"Bt cotton carries insecticidal protein genes taken from the bacterium:","options":["Thermus aquaticus","Bacillus thuringiensis","Agrobacterium tumefaciens","Escherichia coli"],"answer":1,"explanation":"Bt stands for Bacillus thuringiensis, whose cry genes code for insecticidal Bt toxin proteins.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-4","question":"EcoRI recognises the palindromic sequence 5'-GAATTC-3' and cuts each strand between:","options":["G and A","T and C","A and T","A and A"],"answer":0,"explanation":"EcoRI cuts both strands between G and A, a little away from the centre of the palindrome, leaving single-stranded overhangs called sticky ends.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-5","question":"After gel electrophoresis, DNA fragments are made visible by staining with ethidium bromide followed by exposure to:","options":["UV light, showing bright orange bands","Visible light, showing bright blue bands","Infrared light, showing green bands","X-rays, showing dark spots on film"],"answer":0,"explanation":"DNA cannot be seen in visible light without staining; ethidium bromide-stained DNA shows bright orange bands under UV light.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-6","question":"In the E. coli cloning vector pBR322, the gene rop codes for:","options":["Resistance to ampicillin (β-lactamase)","The unique recognition site for enzyme EcoRI","Proteins needed for plasmid replication","Resistance to tetracycline in the host"],"answer":2,"explanation":"In pBR322, ampR and tetR are antibiotic resistance genes, ori is the origin of replication and rop codes for proteins involved in plasmid replication.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-7","question":"When a foreign DNA is inserted within the coding sequence of the enzyme β-galactosidase, the recombinant colonies grown with a chromogenic substrate:","options":["Turn blue, as lacZ stays functional","Stay colourless (appear white)","Turn red with the chromogenic substrate","Fail to grow on the selective medium"],"answer":1,"explanation":"Insertion inactivates β-galactosidase (insertional inactivation), so recombinant colonies cannot act on the chromogenic substrate and stay colourless, while non-recombinant colonies turn blue.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-8","question":"The thermostable DNA polymerase used in the polymerase chain reaction is isolated from:","options":["Haemophilus influenzae","Bacillus thuringiensis","Thermus aquaticus","Escherichia coli"],"answer":2,"explanation":"Taq polymerase, from the bacterium Thermus aquaticus, stays active at the high temperatures used to denature DNA in each PCR cycle.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-9","question":"Rosie, the first transgenic cow (1997), produced milk that:","options":["Was free of lactose for lactose-intolerant infants","Contained α-1-antitrypsin for emphysema","Had human alpha-lactalbumin, 2.4 g per litre","Contained human insulin, 2.4 g per litre"],"answer":2,"explanation":"Rosie produced human protein-enriched milk (2.4 g per litre) containing human alpha-lactalbumin, nutritionally more balanced for human babies than natural cow milk.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-10","question":"A nematode-resistant tobacco plant was developed using RNA interference against:","options":["Heterodera, the cyst nematode of potato roots","Meloidogyne incognita, a root nematode","Wuchereria, a filarial nematode","Aphids feeding on tobacco leaf sap"],"answer":1,"explanation":"Nematode-specific genes were introduced via Agrobacterium vectors to produce both sense and anti-sense RNA; the dsRNA silenced the specific mRNA of Meloidogyne incognita, so the parasite could not survive in the transgenic host.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-11","question":"The proteins encoded by the genes cryIAc and cryIIAb control:","options":["Corn borer","Cotton bollworms","Mosquito larvae","Root-knot nematodes"],"answer":1,"explanation":"cryIAc and cryIIAb proteins control cotton bollworms, whereas cryIAb controls the corn borer.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-12","question":"Bt toxin does not kill the bacterium that makes it but kills insects that eat it because:","options":["It stays an inactive protoxin until the alkaline gut activates it","It becomes active only when bright sunlight strikes the leaf surface","It becomes active only in the acidic pH of the insect gut","The bacterium carries an antidote gene that the insect lacks"],"answer":0,"explanation":"Bt protoxin crystals are solubilised by the alkaline pH of the insect gut; the active toxin binds the midgut epithelial cells and makes pores, causing swelling, lysis and death of the insect.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-13","question":"Insulin is synthesised as a prohormone. Which part of proinsulin is absent from mature insulin?","options":["The A chain","The C peptide","The B chain","The disulphide bridges"],"answer":1,"explanation":"Proinsulin contains an extra stretch, the C peptide, which is removed during maturation. In 1983 Eli Lilly made the A and B chains separately in E. coli and joined them by disulphide bonds.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-14","question":"The first clinical gene therapy, given in 1990 to a 4-year-old girl, treated a deficiency of the enzyme:","options":["Glucose-6-phosphate dehydrogenase","Phenylalanine hydroxylase","Adenosine deaminase (ADA)","β-galactosidase"],"answer":2,"explanation":"ADA deficiency affects the immune system. Lymphocytes from the patient's blood were cultured, a functional ADA cDNA was introduced with a retroviral vector, and the cells were returned to the patient.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-15","question":"The Ti plasmid of Agrobacterium tumefaciens is used as a cloning vector after it is modified so that it:","options":["Causes crown-gall tumours more efficiently in plants","Still delivers genes but no longer causes tumours","Loses its ability to transfer DNA into plant cells","Can replicate only in animal cells, not in plants"],"answer":1,"explanation":"The tumour-inducing Ti plasmid normally transforms plant cells into tumours; the disarmed version still transfers DNA into plant cells but does not cause disease.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-16","question":"To make bacterial cells competent to take up recombinant DNA, they are treated with a specific concentration of a divalent cation and then given a heat shock. The cation and the heat-shock temperature are:","options":["Calcium; 94 °C","Calcium; 42 °C","Magnesium; 72 °C","Sodium; 37 °C"],"answer":1,"explanation":"Cells treated with Ca²⁺ are incubated with rDNA on ice, placed briefly at 42 °C (heat shock) and then put back on ice, which lets the DNA enter. Na⁺ is monovalent, and 72 °C or 94 °C are PCR temperatures.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-17","question":"In biotechnology, 'downstream processing' refers to:","options":["Separating and purifying the product after biosynthesis","Growing the host in a small shake flask before scaling up","Isolating and amplifying the gene of interest by PCR","Transferring rDNA into a competent host cell"],"answer":0,"explanation":"After biosynthesis the product must be separated and purified, then formulated with suitable preservatives and, for drugs, put through clinical trials and quality control.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-18","question":"According to NCERT, how many documented varieties of Basmati rice are grown in India?","options":["1000","200","27","50,000"],"answer":2,"explanation":"India has an estimated 200,000 varieties of rice, of which 27 documented varieties are Basmati. In 1997 an American company got patent rights on Basmati rice through the US Patent and Trademark Office.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-19","question":"How many of the following statements about restriction enzymes are correct?\n(i) Restriction endonucleases recognise specific palindromic nucleotide sequences.\n(ii) In EcoRI, the letter R is derived from the name of the strain (RY13).\n(iii) The Roman numeral in the name indicates the order in which the enzymes were isolated from that strain.\n(iv) EcoRI produces blunt ends without any overhang.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. EcoRI cuts away from the centre of the palindrome and leaves single-stranded sticky ends.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-20","question":"Arrange the steps of recombinant DNA technology in the correct order.\n(i) Ligation of the DNA fragment into a vector\n(ii) Fragmentation of DNA by restriction endonucleases\n(iii) Transfer of the recombinant DNA into the host\n(iv) Isolation of the desired DNA fragment\n(v) Culturing the host cells at large scale and extracting the product","options":["(iv), (ii), (i), (iii), (v)","(ii), (iv), (i), (iii), (v)","(ii), (i), (iv), (iii), (v)","(ii), (iv), (iii), (i), (v)"],"answer":1,"explanation":"After isolating DNA, it is cut, the desired fragment is isolated, ligated into a vector, the rDNA is transferred into the host, and the host is cultured at large scale to extract the product.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-21","question":"Assertion (A): In blue-white screening, recombinant colonies appear blue.\nReason (R): Insertion of foreign DNA into the coding region of β-galactosidase inactivates the enzyme.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false but R is true: because the enzyme is inactivated, recombinant colonies cannot convert the chromogenic substrate and appear white (colourless); non-recombinants turn blue.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-22","question":"Match the tool with its source organism.\nList I: (A) Taq polymerase (B) Ti plasmid (C) cry genes (D) Hind II\nList II: (1) Haemophilus influenzae (2) Bacillus thuringiensis (3) Agrobacterium tumefaciens (4) Thermus aquaticus","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Taq polymerase comes from Thermus aquaticus, the Ti plasmid from Agrobacterium tumefaciens, cry genes from Bacillus thuringiensis and Hind II from Haemophilus influenzae.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-23","question":"How many of the following statements about PCR are correct?\n(i) Each cycle consists of denaturation, annealing and extension.\n(ii) Primers are small, chemically synthesised oligonucleotides complementary to regions of the template DNA.\n(iii) Repeated cycles can amplify a DNA segment to about a billion copies.\n(iv) A thermostable DNA polymerase extends the primers using the nucleotides provided.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Because Taq polymerase survives the high denaturation temperature, cycles can be repeated without adding fresh enzyme.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-24","question":"A PCR is started with 2 molecules of double-stranded target DNA. Assuming every cycle doubles the DNA, how many double-stranded copies are present after 5 cycles?","options":["32","128","64","10"],"answer":2,"explanation":"Copies = initial × 2ⁿ = 2 × 2⁵ = 2 × 32 = 64. The trap 32 forgets that there were two starting molecules.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-25","question":"How many of the following statements about transgenic animals are correct?\n(i) They are used to study how genes regulate normal physiology and development.\n(ii) Transgenic mice are being used to test the safety of the polio vaccine.\n(iii) α-1-antitrypsin produced by transgenic animals is used to treat phenylketonuria.\n(iv) Transgenic mice are being used to test the safety of the smallpox vaccine.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (ii) are correct. α-1-antitrypsin is used to treat emphysema, and NCERT cites testing of the polio vaccine on transgenic mice, not smallpox.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-26","question":"Assertion (A): Conventional methods such as serum and urine analysis cannot detect an infection early.\nReason (R): The concentration of the pathogen is very low in the early stage, before symptoms appear.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: by the time symptoms appear, the pathogen is already at high concentration. Very low amounts of nucleic acid can, however, be detected by amplifying them with PCR.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-27","question":"Which of the following is NOT a desirable feature of a cloning vector?","options":["A single site for a commonly used restriction enzyme","An origin of replication controlling copy number","A selectable marker such as an antibiotic gene","Many recognition sites for one restriction enzyme"],"answer":3,"explanation":"A vector needs a single recognition site for a given restriction enzyme; more than one site would cut the vector into several fragments and complicate cloning.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-28","question":"How many of the following statements about agarose gel electrophoresis are correct?\n(i) DNA fragments are negatively charged and move towards the cathode.\n(ii) Larger fragments move farther than smaller ones.\n(iii) The separated bands are cut out from the gel and extracted, a step called ligation.\n(iv) The DNA fragments are separated according to their size through the sieving effect of the agarose gel.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only (iv) is correct. Negatively charged DNA moves towards the anode, smaller fragments move farther, and extracting the cut-out bands is called elution (ligation is the joining of DNA fragments).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-29","question":"How many of the following statements are correct?\n(i) The Genetic Engineering Approval Committee (GEAC) decides on the validity of GM research and the safety of introducing GM organisms for public services.\n(ii) Biopiracy is the use of bio-resources by multinational companies without proper authorisation from the countries concerned or compensatory payment.\n(iii) The Indian Parliament has cleared the second amendment of the Indian Patents Bill.\n(iv) In 1997 an American company got patent rights on Basmati rice through the US Patent and Trademark Office.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT statements on the ethical issues of biotechnology.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-30","question":"A circular plasmid has three EcoRI sites and a linear DNA molecule also has three EcoRI sites. On complete digestion with EcoRI, the number of fragments produced is respectively:","options":["3 and 3","4 and 3","3 and 4","4 and 4"],"answer":2,"explanation":"Cutting a circle at n sites gives n pieces, while cutting a line at n sites gives n + 1 pieces, so 3 and 4.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-biotechnology-31", "question": "The enzyme that joins the cut ends of DNA fragments by sealing the sugar-phosphate backbone is:", "options": ["DNA ligase", "DNA polymerase", "Restriction endonuclease", "Exonuclease"], "answer": 0, "explanation": "DNA ligase joins DNA fragments; restriction endonucleases cut DNA, and DNA polymerase synthesises new strands.", "difficulty": "easy", "source": "NEET pattern"},
  {"id":"bio-biotechnology-32","question":"Restriction endonucleases are popularly called:","options":["Molecular glue","Molecular scissors","Molecular probes","Molecular carriers"],"answer":1,"explanation":"Restriction enzymes cut DNA at specific sequences, so they are called molecular scissors; ligase acts as the 'glue'.","difficulty":"easy","source":"NEET pattern"},
  {"id": "bio-biotechnology-33", "question": "Large vessels in which raw materials are biologically converted into specific products by microbes, plant, animal or human cells are called:", "options": ["Incubators", "Centrifuges", "Bioreactors", "Electrophoresis tanks"], "answer": 2, "explanation": "Bioreactors provide optimal conditions such as temperature, pH, substrate, salts, vitamins and oxygen for producing the desired product on a large scale.", "difficulty": "easy", "source": "NEET pattern"},
  {"id":"bio-biotechnology-34","question":"Exonucleases differ from endonucleases in that exonucleases:","options":["Cut DNA only at palindromic sites","Act only on RNA, never on DNA","Join DNA fragments, like ligase","Remove nucleotides from DNA ends"],"answer":3,"explanation":"Exonucleases remove nucleotides from the ends of DNA, whereas endonucleases make cuts at specific positions within the DNA.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-35","question":"Selection of recombinants on the basis of the loss of a selectable marker's function, after foreign DNA has been inserted within it, is called:","options":["Insertional inactivation","Heat-shock transformation","Restriction mapping","Transduction"],"answer":0,"explanation":"When foreign DNA is ligated within an antibiotic-resistance gene or the lacZ gene, that gene is inactivated; this insertional inactivation lets recombinants be told apart from non-recombinants.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-36","question":"Genes for resistance to antibiotics such as ampicillin, chloramphenicol, tetracycline or kanamycin are useful selectable markers for E. coli because:","options":["They raise the plasmid copy number in the host cell","Untransformed E. coli lacks resistance to them","They code for the restriction enzymes used in cloning","They make the bacteria competent to take up DNA"],"answer":1,"explanation":"Untransformed E. coli cells are killed by these antibiotics, so only cells that took up a vector carrying the resistance gene survive on antibiotic plates.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-37","question":"In microinjection, the recombinant DNA is:","options":["Shot into plant cells on gold or tungsten particles","Delivered into plant cells by disarmed Agrobacterium","Injected straight into an animal cell's nucleus","Taken up by competent bacteria after heat shock"],"answer":2,"explanation":"Microinjection injects recombinant DNA straight into the nucleus of an animal cell. Biolistics uses DNA-coated gold or tungsten particles, mainly for plants.","difficulty":"moderate","source":"NEET pattern"},
  {"id": "bio-biotechnology-38", "question": "In biolistics (gene gun), plant cells are bombarded with high-velocity micro-particles coated with DNA. These particles are made of:", "options": ["Silver or copper", "Iron or aluminium", "Silica or glass", "Gold or tungsten"], "answer": 3, "explanation": "Gold or tungsten micro-particles coated with DNA are fired into plant cells; the method is suitable for plants.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-biotechnology-39", "question": "ELISA, a technique used for early diagnosis of infection, is based on the principle of:", "options": ["Antigen–antibody interaction", "DNA–DNA hybridisation", "Amplification of nucleic acids", "Separation of DNA by charge"], "answer": 0, "explanation": "ELISA (enzyme-linked immunosorbent assay) detects antigens such as proteins or glycoproteins, or antibodies made against the pathogen, through antigen–antibody interaction.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-biotechnology-40","question":"In 1983, Eli Lilly produced human insulin by recombinant DNA technology. They:","options":["Expressed a single proinsulin gene in E. coli, which then removed the C peptide","Made chains A and B separately in E. coli, then linked them by disulphide bonds","Extracted human insulin from the pancreas of transgenic pigs","Expressed the complete insulin gene in tobacco plants, then purified it"],"answer":1,"explanation":"The A and B chains were made separately in E. coli from two synthetic DNA sequences, extracted, and combined by forming disulphide bonds to give human insulin.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-41","question":"In detecting a mutated gene by hybridisation with a radioactive probe followed by autoradiography, the clone having the mutated gene:","options":["Shows as a dark band, since mutant DNA binds the probe more tightly","Appears only after a further round of PCR amplification","Will not appear, as the probe cannot pair with the mutant gene","Glows orange under UV light because of the probe"],"answer":2,"explanation":"The single-stranded probe binds only to its complementary DNA; a mutated gene lacks full complementarity, so no signal appears for that clone on the film.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-42","question":"The cohesive (sticky) ends produced by restriction enzymes are useful in recombinant DNA work because they:","options":["Stop the vector replicating until ligase seals it","Are methylated by the host, so they resist further cutting","Make the DNA fragments move faster in the gel","Base-pair with matching ends, helping ligase join them"],"answer":3,"explanation":"Single-stranded overhangs on fragments cut with the same enzyme pair up by hydrogen bonding; this stickiness helps DNA ligase seal them into recombinant DNA.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-43","question":"Stirred-tank bioreactors are usually cylindrical or have a curved base in order to:","options":["Facilitate mixing of the reactor contents","Reduce foam formation during aeration","Allow light to reach the culture","Prevent contamination by outside microbes"],"answer":0,"explanation":"A cylindrical shape or curved base helps the stirrer mix the contents evenly and spread oxygen throughout the reactor.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-44","question":"Besides initiating replication, the origin of replication (ori) in a vector also:","options":["Codes for resistance to an antibiotic","Controls copy number of the linked DNA","Determines the maximum size of the insert","Carries the recognition site for EcoRI"],"answer":1,"explanation":"Replication starts at ori, and the ori sequence also controls how many copies of the vector and its linked DNA are made; high copy number is wanted for many copies of the target DNA.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-biotechnology-45", "question": "Agrobacterium tumefaciens is used as a natural genetic engineer for plants. Which vectors, after being disarmed, play a similar role for animal cells?", "options": ["Bacteriophages", "Yeast plasmids", "Retroviruses", "Cosmids"], "answer": 2, "explanation": "Retroviruses can transform normal animal cells into cancerous cells; disarmed retroviruses are used to deliver desirable genes into animal cells.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-46", "question": "In gene therapy for ADA deficiency using lymphocytes, the patient needs periodic infusions of genetically engineered lymphocytes because:", "options": ["The ADA cDNA is lost after one cell division", "The ADA enzyme is destroyed by antibodies", "The retroviral vector kills the lymphocytes", "The engineered lymphocytes are not immortal"], "answer": 3, "explanation": "Lymphocytes grown in culture, given a functional ADA cDNA by a retroviral vector and returned to the patient do not live for ever, so the treatment must be repeated; inserting the gene into early embryonic stage cells could give a permanent cure.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-biotechnology-47","question":"In RNA interference, the complementary double-stranded RNA that silences a specific mRNA may naturally originate from:","options":["RNA viruses, or transposons copied via an RNA intermediate","Ribosomal RNA folding back on itself in the host","Transfer RNA molecules paired with their anticodons","Bacterial plasmids that carry antibiotic-resistance genes in cells"],"answer":0,"explanation":"Natural sources of the dsRNA are RNA viruses and mobile genetic elements (transposons) that replicate via an RNA intermediate; the dsRNA binds and silences the target mRNA.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-biotechnology-48", "question": "According to NCERT, a bioreactor can process culture volumes of the order of:", "options": ["1–10 millilitres", "1–10 litres", "100–1000 litres", "1 million litres"], "answer": 2, "explanation": "Small-volume cultures cannot give appreciable yields, so bioreactors processing large volumes of about 100–1000 litres are used.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-biotechnology-49","question":"How many of the following statements about Bt toxin are correct?\n(i) The toxin does not kill Bacillus itself because it exists there as an inactive protoxin.\n(ii) The activated toxin binds to the surface of midgut epithelial cells and creates pores, causing cell swelling and lysis.\n(iii) The inactive protoxin is converted to the active form by the alkaline pH of the insect gut.\n(iv) The protein encoded by cryIAb controls corn borer.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The protoxin is inactive in the bacterium, becomes active in the alkaline insect gut, binds midgut epithelial cells and creates pores causing lysis; cryIAb codes for a protein that controls the corn borer.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-biotechnology-50", "question": "Match the enzyme used in DNA isolation with its role.\nList I: (A) Lysozyme (B) Cellulase (C) Chitinase (D) Protease\nList II: (1) Breaks the fungal cell wall (2) Removes proteins associated with DNA (3) Breaks the bacterial cell wall (4) Breaks the plant cell wall", "options": ["A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1"], "answer": 1, "explanation": "Lysozyme digests bacterial walls, cellulase plant walls and chitinase fungal walls; proteases remove proteins such as histones and ribonuclease removes RNA.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-51", "question": "A foreign DNA is ligated into the BamHI site of the cloning vector pBR322, and E. coli cells are transformed. The recombinant transformants will:", "options": ["Grow on both ampicillin and tetracycline", "Grow on tetracycline but not on ampicillin", "Grow on ampicillin but not on tetracycline", "Grow on neither antibiotic"], "answer": 2, "explanation": "The BamHI site lies within the tetracycline-resistance gene, so the insert inactivates it; the ampicillin-resistance gene stays intact. Recombinants grow on ampicillin plates but die on tetracycline plates.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-52", "question": "Assertion (A): The restriction endonucleases of a bacterium do not cut the bacterium's own DNA.\nReason (R): The bacterium methylates its own DNA, which protects it from its restriction enzymes.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The restriction system of E. coli has two enzymes: one adds methyl groups to the cell's own DNA and the other cuts unmethylated foreign (phage) DNA. Methylation is why the host DNA is spared.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-53", "question": "How many of the following statements about cloning vectors are correct?\n(i) The origin of replication controls the copy number of the linked DNA.\n(ii) Any piece of DNA linked to the ori can be made to replicate within the host cells.\n(iii) Selectable markers help in identifying and eliminating non-transformants.\n(iv) Transformation is a procedure through which a piece of DNA is introduced into a host bacterium.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Ori starts replication and sets copy number, markers such as ampicillin resistance remove non-transformants, and transformation brings DNA into the host.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-54", "question": "Assume a DNA molecule with a random sequence in which all four bases are equally frequent. A restriction enzyme that recognises a specific 4-base-pair sequence would, on average, cut once in every:", "options": ["16 bp", "64 bp", "256 bp", "4096 bp"], "answer": 2, "explanation": "Each position matches with probability 1/4, so a 4-bp site occurs once in 4⁴ = 256 bp on average. A 6-bp site would occur once in 4⁶ = 4096 bp.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-biotechnology-55","question":"How many of the following statements about molecular diagnosis are correct?\n(i) PCR is used to detect HIV in suspected AIDS patients.\n(ii) PCR is used to detect mutations in genes of suspected cancer patients.\n(iii) A probe is a single-stranded DNA or RNA tagged with a radioactive molecule.\n(iv) ELISA is based on the principle of antigen–antibody interaction.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. PCR detects HIV and cancer-causing gene mutations at very low concentrations, a probe is a tagged single-stranded DNA or RNA, and ELISA works on antigen–antibody interaction, detecting either antigens or antibodies.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-biotechnology-56", "question": "Match the enzyme with its function.\nList I: (A) Restriction endonuclease (B) DNA ligase (C) Taq polymerase (D) Exonuclease\nList II: (1) Joins DNA fragments (2) Removes nucleotides from the ends of DNA (3) Cuts DNA at specific recognition sequences (4) Extends primers during PCR and stays active at high temperature", "options": ["A-3, B-4, C-1, D-2", "A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2"], "answer": 3, "explanation": "Restriction endonucleases cut at recognition sites, ligase joins fragments, thermostable Taq polymerase extends primers in PCR, and exonucleases trim nucleotides from DNA ends.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-57", "question": "Assertion (A): Host cells must be made competent before they can take up recombinant DNA.\nReason (R): DNA is a hydrophilic molecule and cannot pass through cell membranes.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because hydrophilic DNA cannot cross membranes on its own, bacterial cells are first made competent, for example by treatment with divalent cations such as calcium, before transformation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-58", "question": "All of the following statements about the vector pBR322 are correct EXCEPT:", "options": ["The PstI and PvuI sites lie within the tetracycline-resistance gene", "The BamHI and SalI sites lie within the tetracycline-resistance gene", "It has an origin of replication (ori)", "It carries the rop gene, which codes for proteins involved in plasmid replication"], "answer": 0, "explanation": "In pBR322 the PstI and PvuI sites lie within the ampicillin-resistance gene, while BamHI and SalI lie within the tetracycline-resistance gene.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-59", "question": "How many of the following statements about downstream processing are correct?\n(i) Drugs must be subjected to clinical trials before marketing.\n(ii) Strict quality control testing is required for each product.\n(iii) Downstream processing is identical for all biotechnological products.\n(iv) Formulation of the product with suitable preservatives is part of upstream processing.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only (i) and (ii) are correct. Downstream processing and quality control vary from product to product, and formulation with preservatives is part of downstream processing.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-biotechnology-60", "question": "Arrange the steps in isolating DNA from a cell in the correct order.\n(i) Removal of RNA by ribonuclease and of proteins by protease\n(ii) Breaking the cell wall with enzymes such as lysozyme, cellulase or chitinase\n(iii) Addition of chilled ethanol\n(iv) Spooling out the precipitated DNA as fine threads", "options": ["(i), (ii), (iii), (iv)", "(ii), (i), (iii), (iv)", "(ii), (iii), (i), (iv)", "(ii), (i), (iv), (iii)"], "answer": 1, "explanation": "The cell is first opened, then RNA and proteins are removed, then chilled ethanol precipitates the purified DNA, which is spooled out as threads.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-biotechnology-61","question":"In the name of the restriction enzyme EcoRI, the letter 'R' stands for:","options":["Restriction, the enzyme's function","The strain RY13 of the bacterium","Its palindromic recognition sequence","The R plasmid carrying the gene"],"answer":1,"explanation":"In EcoRI, 'E' comes from the genus Escherichia, 'co' from the species coli, 'R' from the strain RY13, and the Roman numeral I gives the order in which the enzyme was isolated from that strain.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-62","question":"Cutting a separated DNA band out of an agarose gel and extracting the DNA from the gel piece is called:","options":["Spooling","Annealing","Elution","Transformation"],"answer":2,"explanation":"Elution recovers the purified DNA fragments from the gel so they can be used to build recombinant DNA. Spooling collects precipitated DNA threads, and annealing is the binding of primers in PCR.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-63","question":"Plants, bacteria, fungi and animals whose genes have been altered by manipulation are called:","options":["Genetically modified organisms (GMOs)","Somaclonal variants of tissue culture","Induced mutants from radiation breeding","Hybrids from conventional crossing"],"answer":0,"explanation":"Organisms whose genes have been changed by deliberate manipulation are called GMOs; Bt cotton is an example. Somaclonal variants, radiation-induced mutants and conventional hybrids arise without any deliberate gene transfer.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-biotechnology-64","question":"During DNA isolation, purified DNA comes out of solution as fine threads after the addition of:","options":["Ethidium bromide","Calcium chloride","Chilled ethanol","Hot phenol"],"answer":2,"explanation":"Adding chilled ethanol makes the purified DNA precipitate as fine threads, which can be removed by spooling. Ethidium bromide stains DNA in gels, and calcium ions make cells competent.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-65","question":"The two core techniques that made modern biotechnology possible are:","options":["Tissue culture and somatic hybridisation","Mutation breeding and induced polyploidy","Fermentation and industrial distillation","Genetic and bioprocess engineering"],"answer":3,"explanation":"Genetic engineering alters the chemistry of the genetic material, and bioprocess engineering keeps a sterile, contamination-free setting so that only the desired microbe or cell grows in large numbers.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-66","question":"Which of the following is NOT one of the three options listed for increasing food production?","options":["Agro-chemical based agriculture","Organic agriculture","Genetically engineered crop-based agriculture","Shifting (jhum) cultivation"],"answer":3,"explanation":"The three options are agro-chemical based agriculture, organic agriculture and genetically engineered crop-based agriculture. Shifting cultivation is not one of them.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-67","question":"Transgenic animals have been used to produce human alpha-1-antitrypsin, a protein used to treat:","options":["Cystic fibrosis","Emphysema","Phenylketonuria","Haemophilia"],"answer":1,"explanation":"Alpha-1-antitrypsin from transgenic animals is used to treat emphysema. Similar attempts are being made for phenylketonuria and cystic fibrosis, but the protein in question is meant for emphysema.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-68","question":"The safety of the polio vaccine is being tested on:","options":["Transgenic mice","Transgenic cows","Transgenic sheep","Transgenic pigs"],"answer":0,"explanation":"Transgenic mice are used to test the safety of vaccines, including the polio vaccine, before they are used on humans. If they prove reliable, they could replace monkeys for such testing.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-69","question":"Before recombinant DNA technology, the insulin used to treat diabetes was extracted from the pancreas of:","options":["Slaughtered sheep and goats","Sharks and other fish","Slaughtered cattle and pigs","Horses used for antisera"],"answer":2,"explanation":"Insulin was once extracted from the pancreas of slaughtered cattle and pigs. Being a foreign protein, it caused allergy or other reactions in some patients.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-biotechnology-70","question":"In the cloning vector pBR322, which pair of restriction sites lies within the tetracycline resistance gene (tetR)?","options":["PstI and PvuI","BamHI and SalI","PstI and SalI","EcoRI and PvuII"],"answer":1,"explanation":"In pBR322, BamHI and SalI sites lie in the tetR gene, while PstI and PvuI sites lie in the ampicillin resistance gene (ampR).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-71","question":"The first recombinant DNA was made by linking an antibiotic resistance gene to a native plasmid of:","options":["Escherichia coli","Agrobacterium tumefaciens","Salmonella typhimurium","Bacillus thuringiensis"],"answer":2,"explanation":"Stanley Cohen and Herbert Boyer (1972) cut out an antibiotic resistance gene and linked it to a native plasmid of Salmonella typhimurium. E. coli later became the most common cloning host.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-72","question":"In 1963, two enzymes responsible for restricting the growth of bacteriophage in Escherichia coli were isolated. What did they do?","options":["One methylated DNA and the other cut it","Both joined DNA fragments like ligase","One unwound DNA and the other made primers","Both broke down the viral RNA genome"],"answer":0,"explanation":"One enzyme methylated DNA and the other, a restriction endonuclease, cut DNA. Methylation protects the bacterium's own DNA from its restriction enzymes.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-73","question":"About how many restriction enzymes have been isolated, and from how many bacterial strains?","options":["About 90, from 23 strains","More than 9,000, from over 2,300 strains","About 300, from 50 strains","More than 900, from over 230 strains"],"answer":3,"explanation":"More than 900 restriction enzymes have been isolated from over 230 strains of bacteria, each recognising a different sequence.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-74","question":"Some plasmids are present as only one or two copies per cell. Others may have about:","options":["500 to 1,000 copies per cell","5 to 10 copies per cell","15 to 100 copies per cell","More than 10,000 copies per cell"],"answer":2,"explanation":"Plasmid copy number ranges from one or two to 15 to 100 copies per cell. Bacteriophages, being numerous per cell, have even higher copy numbers of their genome.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-75","question":"The Bt toxin gene cryIAb protects crops against:","options":["Cotton bollworms","Corn borer","Aphids","Root-knot nematodes"],"answer":1,"explanation":"The protein encoded by cryIAb controls the corn borer, while cryIAc and cryIIAb proteins control cotton bollworms. Nematodes are controlled by RNA interference, not by Bt toxin.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-76","question":"About how many varieties of rice are estimated to exist in India alone?","options":["27","2,000","20,000","200,000"],"answer":3,"explanation":"India has about 200,000 rice varieties, one of the richest rice diversities in the world. The figure 27 is the number of documented Basmati varieties.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-77","question":"In 1997, an American company obtained patent rights on Basmati rice through the:","options":["World Trade Organization","US Patent and Trademark Office","Genetic Engineering Approval Committee","Food and Agriculture Organization"],"answer":1,"explanation":"The patent was granted by the US Patent and Trademark Office. The 'new' variety had in fact been derived by crossing Indian farmers' Basmati with semi-dwarf varieties.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-78","question":"The European Federation of Biotechnology (EFB) defines biotechnology as:","options":["Integrating natural science with organisms, cells, parts or analogues for products and services","The use of live microbes only to ferment curd, bread, wine and beer","The chemical synthesis of drugs and vaccines without using any living cells or their parts","The improvement of crop plants and livestock by selection and hybridisation alone"],"answer":0,"explanation":"The EFB definition covers both traditional and modern molecular biotechnology. Fermentation is only one part of biotechnology, and conventional breeding does not by itself fit the definition.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-79","question":"Match the item with what it is linked to.\nList I: (A) Rosie (B) Alpha-1-antitrypsin (C) Meloidogyne incognita (D) Adenosine deaminase deficiency\nList II: (1) Emphysema (2) RNA interference (3) Milk enriched with human alpha-lactalbumin (4) First clinical gene therapy, 1990","options":["A-3, B-2, C-1, D-4","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"answer":3,"explanation":"The transgenic cow Rosie gave milk containing human alpha-lactalbumin. Alpha-1-antitrypsin treats emphysema, the nematode Meloidogyne incognita was controlled by RNA interference, and ADA deficiency was the target of the first gene therapy in 1990.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-80","question":"How many of the following are the critical research areas of biotechnology?\n(i) Providing the best catalyst as an improved organism, usually a microbe, or a pure enzyme\n(ii) Creating optimal conditions through engineering for the catalyst to act\n(iii) Downstream processing technologies to purify the protein or organic compound\n(iv) Breeding new crop varieties only by hybridisation and selection","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"The three critical research areas are (i), (ii) and (iii). Conventional breeding by hybridisation and selection is not one of them.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-81","question":"How many of the following statements about genetically modified crops are correct?\n(i) They have been made more tolerant to abiotic stresses such as cold, drought, salt and heat.\n(ii) They have reduced reliance on chemical pesticides.\n(iii) They have helped to reduce post-harvest losses.\n(iv) They have increased the efficiency of mineral use by plants.\n(v) Bt crops are protected against all insect pests, so no other pest management is ever needed.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. Bt toxins act on particular insect groups, such as lepidopterans, coleopterans and dipterans, not on all insects.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-82","question":"How many of the following statements about restriction enzymes are correct?\n(i) The first letter of the name comes from the genus and the next two letters from the species of the bacterium.\n(ii) The Roman numeral shows the order in which the enzymes were isolated from that strain.\n(iii) Restriction enzymes belong to a larger class of enzymes called nucleases.\n(iv) A restriction endonuclease inspects the length of a DNA sequence and binds to the DNA at its recognition sequence.\n(v) EcoRI produces blunt ends.","options":["Only two","Only four","Only three","All five"],"answer":1,"explanation":"Statements (i) to (iv) are correct. EcoRI cuts a little away from the centre of the palindrome on both strands, leaving sticky ends, not blunt ends.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-83","question":"Assertion (A): A cloning vector should preferably have a single recognition site for the restriction enzyme being used.\nReason (R): More than one recognition site within the vector would produce several fragments, which complicates gene cloning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. A single site means the vector opens at one place only, so R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-84","question":"Assertion (A): A continuous culture system gives a larger biomass and higher yields of the desired protein than a batch culture.\nReason (R): In continuous culture, used medium is drained out and fresh medium added, so the cells stay in their physiologically most active log (exponential) phase.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. Keeping the cells in the log phase is exactly why continuous culture gives more biomass, so R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-85","question":"Match the term with its description.\nList I: (A) Biopiracy (B) Elution (C) Spooling (D) Transformation\nList II: (1) Introducing a piece of DNA into a host bacterium (2) Collecting precipitated DNA threads (3) Use of bio-resources by multinational companies without proper authorisation or compensation (4) Extracting a separated DNA fragment from a gel piece","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-1, B-4, C-2, D-3","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Biopiracy is unauthorised, uncompensated use of bio-resources; elution recovers DNA from a gel; spooling collects precipitated DNA; transformation introduces DNA into a host bacterium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-86","question":"From the following list, how many are components of a bioreactor?\nAgitator system, oxygen delivery system, foam control system, temperature control system, pH control system, sampling ports, gel electrophoresis tank","options":["Four","Five","Seven","Six"],"answer":3,"explanation":"The first six are bioreactor components; sampling ports let small volumes of culture be withdrawn periodically. A gel electrophoresis tank is used to separate DNA fragments and is not part of a bioreactor.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-87","question":"How many of the following statements about adenosine deaminase (ADA) deficiency are correct?\n(i) It is caused by deletion of the gene for adenosine deaminase.\n(ii) In some children it can be cured by bone marrow transplantation.\n(iii) Enzyme replacement therapy is completely curative.\n(iv) In gene therapy, functional ADA cDNA is introduced into the patient's cultured lymphocytes using a retroviral vector.\n(v) A permanent cure may be possible if the gene from marrow cells producing ADA is introduced into cells at early embryonic stages.","options":["Only two","Only three","All five","Only four"],"answer":3,"explanation":"Statements (i), (ii), (iv) and (v) are correct. Neither bone marrow transplantation nor enzyme replacement therapy is completely curative.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-88","question":"A palindrome in DNA reads the same on both strands when each is read in the 5' to 3' direction. How many of the following top-strand sequences (5' to 3') are palindromic?\nGAATTC, GGATCC, AAGCTT, GTTAAC, GACTTC, CAGCTG","options":["Three","Four","Five","Six"],"answer":2,"explanation":"For each sequence, write the complementary strand and read it 5' to 3'. GAATTC, GGATCC, AAGCTT, GTTAAC and CAGCTG are their own reverse complements; the reverse complement of GACTTC is GAAGTC, so it is not palindromic.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-89","question":"A foreign DNA is ligated into the PstI site of pBR322 and E. coli cells are transformed. How do the recombinant transformants behave?","options":["They grow on both ampicillin and tetracycline","They grow on ampicillin but not on tetracycline","They grow on tetracycline but not on ampicillin","They grow on neither antibiotic"],"answer":2,"explanation":"The PstI site lies in the ampR gene, so the insert inactivates ampicillin resistance while tetracycline resistance stays intact. Non-recombinant plasmids would grow on both antibiotics.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-90","question":"How many of the following statements about biopiracy and the Basmati patent are correct?\n(i) Biopiracy is the use of bio-resources by multinational companies without proper authorisation from the countries and people concerned and without compensatory payment.\n(ii) The Indian Parliament has cleared the first amendment of the Indian Patents Bill, which takes such issues into consideration.\n(iii) Industrialised nations are richer in biodiversity and traditional knowledge than developing nations.\n(iv) The patented 'new' Basmati had been derived by crossing Indian farmers' Basmati with semi-dwarf varieties.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(i) and (iv) are correct. (ii) is wrong: it was the second amendment of the Indian Patents Bill that took such issues into consideration. (iii) is wrong: industrialised nations are rich financially but poor in biodiversity and traditional knowledge.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-biotechnology-91","question":"A foreign gene is ligated into the SalI site of pBR322 and the ligation mixture is used to transform E. coli. Three kinds of colonies are then found: X grows on both ampicillin and tetracycline plates, Y grows on ampicillin but not on tetracycline, and Z grows on neither. Which interpretation is correct?","options":["X carries the recombinant plasmid, Y carries the non-recombinant plasmid, Z is untransformed","X is untransformed, Y carries the recombinant plasmid, Z carries the non-recombinant plasmid","X carries the non-recombinant plasmid, Y carries the recombinant plasmid, Z is untransformed","X carries the non-recombinant plasmid, Y is untransformed, Z carries the recombinant plasmid"],"answer":2,"explanation":"The SalI site lies in tetR, so an insert inactivates tetracycline resistance while ampR stays intact: recombinants grow on ampicillin only (Y). An intact plasmid confers both resistances (X), and cells that took up no plasmid grow on neither (Z).","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-biotechnology-92","question":"A radioactive single-stranded probe complementary to the NORMAL sequence of a gene is hybridised with a set of cell clones, followed by autoradiography. A clone carrying a mutated form of that gene will:","options":["not appear on the photographic film, because the probe cannot pair with the mutated gene","appear as a darker spot, because the mutated gene binds more probe","appear exactly like a normal clone, because hybridisation does not depend on sequence","appear only if the clone is first treated with a restriction enzyme to remove the mutation"],"answer":0,"explanation":"Detection depends on complementary base pairing: a probe made against the normal sequence will not hybridise to the mutated gene, so that clone leaves no signal on the film. This is how a mutated gene is picked out among normal ones.","difficulty":"hard","source":"NEET"},
  {"id":"bio-biotechnology-93","question":"How did RNA interference make tobacco plants resistant to the nematode Meloidogyne incognita?","options":["The transgenic plant made a Bt-like protein that formed pores in the gut cells of the nematode","The plant was made to produce only antisense RNA against its own root mRNA, so the roots became unpalatable to the nematode","A virus vector was used to make dsRNA inside the nematode before it infected the roots","The plant made sense and antisense RNA of a nematode gene; the dsRNA silenced that nematode mRNA"],"answer":3,"explanation":"Agrobacterium vectors delivered nematode-specific DNA arranged to give both sense and antisense RNA in host cells. The two complementary strands formed dsRNA, which triggered RNAi and silenced the nematode's specific mRNA, so the parasite could not survive in the transgenic host.","difficulty":"hard","source":"NEET"},
  {"id":"bio-biotechnology-94","question":"Which statement correctly describes how Eli Lilly produced human insulin by recombinant DNA technology in 1983?","options":["A single proinsulin gene was expressed in E. coli, and bacterial enzymes then cut out the C-peptide","A and B chain DNA went into E. coli plasmids; chains were made separately, extracted and joined by disulphide bonds","The A and B chain genes were placed in one plasmid so that E. coli secreted fully folded insulin with its disulphide bonds already formed","The A and B chains were produced in the milk of transgenic cattle and joined by peptide bonds"],"answer":1,"explanation":"The two chains were made separately in E. coli, then extracted and combined by creating disulphide bridges. This sidestepped the problem of processing proinsulin, since bacteria cannot remove the C-peptide.","difficulty":"hard","source":"NEET"},
  {"id":"bio-biotechnology-95","question":"Arrange the steps used to force recombinant DNA into E. coli by the chemical (heat-shock) method in the correct order.\n(i) Brief incubation at 42 degrees C\n(ii) Treatment of the cells with a divalent cation such as calcium\n(iii) Incubation of the cells with recombinant DNA on ice\n(iv) Returning the cells to ice","options":["(iii), (ii), (i), (iv)","(ii), (i), (iii), (iv)","(ii), (iii), (i), (iv)","(i), (ii), (iii), (iv)"],"answer":2,"explanation":"Cells are first made competent with a divalent cation such as Ca²⁺, then incubated with the recombinant DNA on ice, given a brief heat shock at 42 degrees C and put back on ice. The heat shock comes after the DNA has been added; giving it first would achieve nothing.","difficulty":"hard","source":"NEET"},
  {"id":"bio-biotechnology-96","question":"Match the method of introducing recombinant DNA with its description.\nList I: (A) Microinjection (B) Biolistics (gene gun) (C) Disarmed pathogen vector (D) Treatment with calcium ions\nList II: (i) DNA injected directly into the nucleus of an animal cell (ii) Plant cells bombarded with high-velocity gold or tungsten particles coated with DNA (iii) The vector transfers the DNA when it is allowed to infect the cell (iv) Makes bacterial cells competent to take up DNA","options":["A-i, B-ii, C-iii, D-iv","A-ii, B-i, C-iii, D-iv","A-i, B-iii, C-ii, D-iv","A-iv, B-ii, C-iii, D-i"],"answer":0,"explanation":"Microinjection suits animal cell nuclei, the gene gun is used mainly for plant cells, disarmed pathogens deliver DNA by infection, and divalent cations make bacteria competent.","difficulty":"moderate","source":"NEET"},
  {"id":"bio-biotechnology-97","question":"To isolate pure DNA, the cell or contaminant is treated with a specific enzyme. Match them.\nList I: (A) Bacterial cell (B) Plant cell (C) Fungal cell (D) Contaminating RNA\nList II: (i) Chitinase (ii) Lysozyme (iii) Ribonuclease (iv) Cellulase","options":["A-iv, B-ii, C-i, D-iii","A-ii, B-i, C-iv, D-iii","A-ii, B-iv, C-iii, D-i","A-ii, B-iv, C-i, D-iii"],"answer":3,"explanation":"The enzyme must match the wall: lysozyme for the bacterial wall, cellulase for the plant wall and chitinase for the fungal wall. RNA is removed with ribonuclease and proteins with protease, after which chilled ethanol precipitates the DNA.","difficulty":"moderate","source":"NEET"},
  {"id":"bio-biotechnology-98","question":"How many of the following statements about bioreactors are correct?\n(i) Stirred-tank reactors are usually cylindrical or have a curved base to help mixing.\n(ii) The stirrer helps even mixing and makes oxygen available throughout the reactor.\n(iii) In a sparged stirred-tank reactor, sterile air is bubbled through the culture.\n(iv) Large-scale production uses bioreactors that hold about 100 to 1000 litres of culture.\n(v) A bioreactor provides optimal temperature, pH, substrate, salts, vitamins and oxygen.\n(vi) A foam control system is unnecessary because the stirrer breaks any foam.","options":["4","5","6","3"],"answer":1,"explanation":"Statements (i) to (v) are correct. A bioreactor does need a foam control system, along with the agitator, oxygen delivery, temperature control, pH control and sampling ports, so (vi) is wrong and the count is 5.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-biotechnology-99","question":"A 5 kb circular plasmid has exactly one EcoRI site and one BamHI site, 1.5 kb apart along the shorter arc. After complete digestion with both enzymes, the products are run on an agarose gel. What is seen?","options":["Two bands, with the 1.5 kb fragment travelling farthest from the well","Two bands, with the 3.5 kb fragment travelling farthest from the well","Three bands, with the 1.5 kb fragment travelling farthest from the well","A single 5 kb band, because a circular plasmid is not cut into pieces"],"answer":0,"explanation":"Two cuts in a circle give two fragments (1.5 kb and 3.5 kb), not three as two cuts in a linear molecule would. DNA moves towards the anode through the gel's sieve, so the smaller 1.5 kb fragment moves farther.","difficulty":"hard","source":"NEET"},
  {"id":"bio-biotechnology-100","question":"Assertion (A): An alien piece of DNA can multiply in a host cell only if it is linked to an origin of replication.\nReason (R): The origin of replication also controls the copy number of the linked DNA.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true. A holds because replication starts at the ori, so DNA linked to it can be replicated; controlling copy number is a separate property of the ori and does not explain why replication needs it.","difficulty":"very-hard","source":"NEET"},
  {"id":"bio-biotechnology-101","question":"A circular plasmid has two EcoRI sites and one BamHI site, all at different positions. If it is digested completely with EcoRI and BamHI together, how many DNA fragments are produced?","options":["2","3","4","5"],"answer":1,"explanation":"Cutting a circle at n points gives n fragments, so three cut sites in all give three fragments. A linear molecule with the same three sites would give four.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-102","question":"A restriction enzyme recognises a specific 6-bp sequence. In a linear DNA of 40,960 bp with a random sequence of equally frequent bases, how many fragments are expected after complete digestion?","options":["6","10","11","12"],"answer":2,"explanation":"A given 6-bp sequence is expected once every 4⁶ = 4,096 bp, so about 40,960 ÷ 4,096 = 10 sites. Ten cuts in a linear molecule give 11 fragments; 10 is the trap of counting sites instead of pieces.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-103","question":"NCERT states that repeated PCR can amplify a DNA segment approximately a billion times. Assuming each cycle exactly doubles the DNA, about how many cycles does this need?","options":["10","20","30","40"],"answer":2,"explanation":"2¹⁰ ≈ 10³, so 2³⁰ ≈ 10⁹, about one billion. Twenty cycles give only about a million copies, and forty about a trillion.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-104","question":"A PCR starts with a single double-stranded target DNA molecule and runs for 5 cycles, each cycle doubling the DNA. How many primer molecules have been built into the newly made strands?","options":["30","32","62","64"],"answer":2,"explanation":"After 5 cycles there are 2⁵ = 32 duplexes, i.e. 64 strands. Two are the original template strands, so 62 strands are new, and each new strand starts from one primer.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-105","question":"Into which restriction site of pBR322 could a foreign DNA be inserted while leaving BOTH antibiotic resistance genes intact?","options":["PvuII","BamHI","PstI","SalI"],"answer":0,"explanation":"BamHI and SalI lie in the tetracycline resistance gene and PstI in the ampicillin resistance gene, so inserts there inactivate one marker. The PvuII site, near rop and ori, lies in neither gene.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-106","question":"In a blue-white screening experiment based on insertional inactivation of β-galactosidase, the chromogenic substrate is accidentally left out of the medium. What will be seen?","options":["Recombinant colonies will appear blue and non-recombinants white","All transformed colonies will appear blue","Only recombinant colonies will grow on the medium","Recombinants and non-recombinants will look alike"],"answer":3,"explanation":"The blue colour is produced only when β-galactosidase acts on the chromogenic substrate. Without it no colony turns blue, so recombinants can no longer be distinguished.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-107","question":"How many of the following statements are correct?\n(i) The Ti plasmid of Agrobacterium tumefaciens can transform normal plant cells into a tumour.\n(ii) Retroviruses in animals can transform normal cells into cancerous cells.\n(iii) Disarmed retroviruses are used to deliver desirable genes into animal cells.\n(iv) Agrobacterium tumefaciens is a pathogen of several dicot plants.\n(v) A disarmed Ti plasmid used as a cloning vector still induces tumours in the host plant.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i)–(iv) are correct. The Ti plasmid used as a vector is modified so that it is no longer pathogenic but can still deliver genes, so (v) is wrong.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-108","question":"In a sparged stirred-tank bioreactor, sterile air is bubbled through the culture mainly to:","options":["Remove the carbon dioxide so that the pH stays constant","Increase the surface area available for oxygen transfer","Cool the culture by evaporating part of the medium","Keep foam from forming at the top of the vessel"],"answer":1,"explanation":"Sparging pushes sterile air through as bubbles, greatly increasing the area for oxygen transfer to the cells. Foam and pH are handled by separate control systems.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-109","question":"In downstream processing, after separation and purification, the product is formulated with suitable:","options":["Restriction enzymes","Preservatives","Selectable markers","Cloning vectors"],"answer":1,"explanation":"The purified product is formulated with preservatives, and drugs then go through clinical trials and strict quality control.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-biotechnology-110","question":"Arrange the events by which Bt toxin kills an insect in the correct order.\n(i) The toxin binds to the surface of midgut epithelial cells and creates pores.\n(ii) The insect eats the inactive protoxin crystals.\n(iii) The cells swell and lyse, and the insect dies.\n(iv) The alkaline pH of the gut solubilises the crystals, giving the active toxin.","options":["(ii), (i), (iv), (iii)","(iv), (ii), (i), (iii)","(ii), (iv), (iii), (i)","(ii), (iv), (i), (iii)"],"answer":3,"explanation":"The protoxin is eaten, activated by the alkaline gut pH, binds midgut epithelial cells to make pores, and the cells then swell and lyse.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-111","question":"How many of the following statements about RNA interference (RNAi) are correct?\n(i) RNAi takes place in all eukaryotic organisms as a method of cellular defence.\n(ii) A complementary dsRNA binds to a specific mRNA and prevents its translation.\n(iii) The dsRNA may come from infection by viruses with RNA genomes or from transposons that replicate through an RNA intermediate.\n(iv) In nematode-resistant tobacco, nematode-specific genes were introduced using Agrobacterium vectors.\n(v) The transgenic tobacco produced only antisense RNA, which by itself silenced the parasite.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i)–(iv) are correct. The introduced DNA produced both sense and antisense RNA, which paired to form the dsRNA that triggered RNAi, so (v) is wrong.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-112","question":"Insulin extracted from the pancreas of slaughtered cattle and pigs was not ideal for diabetic patients mainly because it:","options":["Caused allergy or other reactions to the foreign protein in some patients","Lacked the A chain and was therefore completely inactive in humans","Contained the C peptide, which blocks the insulin receptors of human cells","Was a steroid hormone that could not be injected safely into humans"],"answer":0,"explanation":"Animal insulin caused some patients to develop allergy or other reactions to a foreign protein, which is why human insulin made by recombinant DNA technology was preferred.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-biotechnology-113","question":"According to NCERT, a possible PERMANENT cure for ADA deficiency would be to:","options":["Give regular injections of functional ADA enzyme throughout life","Infuse the patient's lymphocytes carrying ADA cDNA every few months","Transplant bone marrow from a matching donor on a single occasion","Introduce the ADA gene from marrow cells into early embryonic cells"],"answer":3,"explanation":"Engineered lymphocytes are not immortal, and enzyme replacement or marrow transplant is not completely curative. NCERT says introducing the gene from marrow cells at early embryonic stages could be a permanent cure.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-114","question":"Which pair of treatments for ADA deficiency does NCERT describe as NOT completely curative?","options":["Gene therapy and bone marrow transplantation","Marrow transplant and enzyme replacement therapy","Enzyme replacement therapy and gene silencing by RNAi","Gene therapy and enzyme replacement therapy"],"answer":1,"explanation":"Bone marrow transplantation and enzyme replacement therapy (injecting functional ADA) help in some cases but are not completely curative; gene therapy is the newer approach.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-115","question":"Of all the transgenic animals that exist, over 95 per cent are:","options":["Cows","Mice","Pigs","Sheep"],"answer":1,"explanation":"Although rabbits, pigs, sheep, cows and fish have been made transgenic, over 95% of all existing transgenic animals are mice.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-biotechnology-116","question":"Match the purpose of transgenic animals with its example.\nList I: (A) Normal physiology and development (B) Biological products (C) Vaccine safety (D) Chemical safety testing\nList II: (1) Alpha-1-antitrypsin for emphysema (2) Toxicity testing with results obtained in less time (3) Studying the role of insulin-like growth factor (4) Testing the polio vaccine in mice","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"Insulin-like growth factor studies show normal physiology; alpha-1-antitrypsin is a biological product; polio vaccine is tested on transgenic mice; and transgenic animals give toxicity results faster.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-117","question":"Golden rice, a genetically modified crop with enhanced nutritional value, is enriched in:","options":["Vitamin B₁₂","Vitamin D","Iron and zinc","Vitamin A"],"answer":3,"explanation":"NCERT cites golden rice, i.e. vitamin A enriched rice, as an example of a GM crop with enhanced nutritional value.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-biotechnology-118","question":"In the name of the restriction enzyme HindII, the letters 'Hin' are derived from:","options":["The genus Haemophilus and the species influenzae","The host strain H and the first enzyme isolated, i","The genus Hind and the order of isolation, II","The species name of the host and the year of isolation"],"answer":0,"explanation":"The first letter comes from the genus (Haemophilus) and the next two from the species (influenzae). The Roman numeral gives the order in which the enzyme was isolated from that strain.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-119","question":"EcoRI recognises 5′-GAATTC-3′ and cuts each strand between G and A. The single-stranded sticky end left on each fragment is:","options":["5′-GAATTC-3′, protruding at the 5′ end","5′-AATT-3′, protruding at the 3′ end","5′-AT-3′, protruding at the 3′ end","5′-AATT-3′, protruding at the 5′ end"],"answer":3,"explanation":"Cutting G^AATTC on both strands leaves the four bases AATT unpaired at the 5′ end of each fragment. Only those four bases overhang, not the whole site.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-120","question":"Which of the following double-stranded sequences (top strand shown) is a palindrome in the sense used for restriction sites?","options":["5′-GATTAG-3′","5′-GATGAT-3′","5′-ACGGCA-3′","5′-GGATCC-3′"],"answer":3,"explanation":"A DNA palindrome reads the same on both strands in the 5′→3′ direction: the complementary strand of GGATCC, read 5′→3′, is also GGATCC. GATTAG and ACGGCA are only mirror images on one strand.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-121","question":"Assertion (A): The DNA polymerase used in PCR is isolated from Thermus aquaticus.\nReason (R): This enzyme remains active during the high temperature used to denature double-stranded DNA.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Taq polymerase is thermostable, so it survives the repeated denaturation steps; that is exactly why it is chosen for PCR.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-122","question":"Which method of introducing recombinant DNA into host cells does NCERT describe as suitable for plants?","options":["Microinjection into the nucleus","Heat shock after treatment with calcium","Infection with disarmed retroviruses","Biolistics, or the gene gun"],"answer":3,"explanation":"In biolistics, plant cells are bombarded with gold or tungsten particles coated with DNA. Microinjection targets animal cell nuclei, and heat shock with calcium is used for bacteria.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-123","question":"When a human protein-coding gene is expressed in a bacterial host such as E. coli, the protein so produced is called a:","options":["Recombinant protein","Native protein","Prosthetic protein","Restriction protein"],"answer":0,"explanation":"A protein encoded by a gene expressed in a heterologous host after cloning is called a recombinant protein.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-biotechnology-124","question":"A linear DNA of 12 kb has EcoRI sites at 3 kb and 8 kb and a BamHI site at 5 kb from its left end. After complete digestion with both enzymes, how many distinct bands are seen on an agarose gel?","options":["2","3","4","5"],"answer":1,"explanation":"Three cuts give four fragments: 3, 2, 3 and 4 kb. The two 3 kb fragments run together, so only three distinct bands (2, 3 and 4 kb) appear.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-125","question":"The piece of DNA that Agrobacterium tumefaciens delivers into a plant cell, transforming it into a tumour cell, is called:","options":["Ti plasmid","T-DNA","Retroposon","cDNA"],"answer":1,"explanation":"Agrobacterium delivers a piece of DNA called T-DNA to transform normal plant cells; the T-DNA is part of the Ti plasmid, which stays in the bacterium.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-biotechnology-126","question":"NCERT lists three basic steps in genetically modifying an organism. Which of the following is NOT one of them?","options":["Identifying DNA with desirable genes","Removing all native plasmids from the host","Introducing the identified DNA into the host","Maintaining the introduced DNA in the host and transferring it to its progeny"],"answer":1,"explanation":"The three steps are identification of DNA with desirable genes, its introduction into the host, and its maintenance in the host and transfer to progeny. Removing native plasmids is not a step.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-127","question":"Assertion (A): Genetic engineering overcomes a major limitation of traditional hybridisation.\nReason (R): Genetic engineering can introduce only the desired gene or set of genes, without carrying along undesirable genes.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Traditional hybridisation often brings in undesirable genes along with the desired ones; isolating and introducing only the desired genes avoids this, so R explains A.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-128","question":"To recover many copies of a target DNA, it should be cloned into a vector whose:","options":["Selectable marker gene is ampicillin resistance","Origin of replication supports a high copy number","Recognition sites for one enzyme are as many as possible","Size is large enough to carry the whole host genome"],"answer":1,"explanation":"The ori controls the copy number of linked DNA, so a high-copy ori yields many copies of the target. Multiple sites for the same enzyme are undesirable in a vector.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-129","question":"Foreign DNA is ligated into the BamHI site of pBR322, E. coli is transformed with the mixture, and the cells are plated on ampicillin. The colonies that grow are:","options":["Only recombinants, since the insert adds resistance","Only non-recombinants, since the insert disrupts ampR","Recombinant and non-recombinant transformants","Both transformed and untransformed cells"],"answer":2,"explanation":"An insert at BamHI disrupts only the tetracycline gene, so every cell carrying the plasmid, with or without insert, resists ampicillin. Untransformed cells die. Replica plating on tetracycline is needed to pick out recombinants.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-130","question":"According to NCERT, Bt toxin proteins are specific to insects belonging to:","options":["Lepidoptera, Coleoptera and Diptera","Hymenoptera, Coleoptera and Hemiptera","Lepidoptera, Orthoptera and Hymenoptera","Diptera, Hemiptera and Orthoptera"],"answer":0,"explanation":"Bt toxins kill lepidopterans (tobacco budworm, armyworm), coleopterans (beetles) and dipterans (flies, mosquitoes).","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-biotechnology-131","question":"In a continuous culture system, the cells are maintained in their:","options":["Lag phase, before division begins","Stationary phase, when growth stops","Death phase, as nutrients run out","Log phase, of exponential growth"],"answer":3,"explanation":"Used medium is drained out and fresh medium added continuously, keeping cells in their physiologically most active log phase, which gives more biomass and product.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-132","question":"In mature human insulin, the A and B polypeptide chains are held together by:","options":["Peptide bonds","Hydrogen bonds","Disulphide bridges","Phosphodiester bonds"],"answer":2,"explanation":"Insulin has two short chains, A and B, linked by disulphide bridges. Eli Lilly made the chains separately and combined them by creating these bonds.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-133","question":"Why must a vector and the source DNA usually be cut with the same restriction enzyme?","options":["So that the vector gains a second ori from the source DNA","So that the enzyme can also seal the joined fragments","So that the source DNA becomes resistant to ampicillin","So both get matching sticky ends that DNA ligase can join"],"answer":3,"explanation":"Cutting both with the same enzyme gives matching sticky ends that pair by hydrogen bonds and are then sealed by DNA ligase; the restriction enzyme itself cannot join DNA.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-biotechnology-134","question":"Assertion (A): DNA bands in an agarose gel are seen only after staining with ethidium bromide and exposure to UV light.\nReason (R): Pure DNA fragments cannot be seen in visible light without staining.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCERT notes that pure DNA cannot be seen in visible light without staining, which is why ethidium bromide and UV are used; the bands appear bright orange.","difficulty":"hard","source":"NEET UG"},
];

export default questions;
